import {seed,today,xpFor,progress,level,uid,complete,purchase,validate} from './engine.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=validate(JSON.parse(localStorage.getItem('daemon-deck')))}catch{state=seed()}
let page='deck',filter='active',query='',sort='suggested',selectedCategory='all',editingImage='',editorContext=null;
const icons={deck:'▦',missions:'⚑',skills:'◈',rewards:'♜',journal:'▤',settings:'⚙'};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function save(){try{localStorage.setItem('daemon-deck',JSON.stringify(state));return true}catch{toast('Storage is full. Export a backup, then use smaller images.');return false}}
function art(x,cls=''){return x.image?`<img class="item-art ${cls}" src="${esc(x.image)}" alt="">`:`<span class="item-art ${cls}">${esc(x.icon||'✧')}</span>`}
function bar(x){const p=progress(x);return `<div class="bar"><i style="width:${p.current/p.total*100}%"></i></div>`}
function render(){document.documentElement.style.setProperty('--accent',state.settings.accent);document.body.classList.toggle('light',!!state.settings.light);document.body.classList.toggle('compact',!!state.settings.compact);const p=progress(state.profile.xp);$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#deck"><img src="icon.svg" alt="">DAEMON<span>DECK</span></a><div class="workspace-label">YOUR PERSONAL CAMPAIGN</div><nav>${[['deck','The deck'],['missions','Missions'],['skills','Skills'],['rewards','Reward shop'],['journal','Activity log']].map(([k,v])=>`<button class="nav-item ${page===k?'active':''}" data-page="${k}"><span>${icons[k]}</span>${v}${k==='missions'?`<small>${state.missions.filter(m=>m.status==='active').length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local"><i></i> Offline ready · Saved on this device</div><button class="nav-item ${page==='settings'?'active':''}" data-page="settings"><span>⚙</span>Settings & appearance</button><button class="profile-mini" data-action="profile">${state.profile.avatar?`<img src="${esc(state.profile.avatar)}" alt="">`:'<span>✦</span>'}<div><b>${esc(state.profile.name)}</b><small>Level ${p.level} · ${esc(state.profile.title)}</small></div><span>↗</span></button></div></aside><main><header class="topbar"><div class="breadcrumb">Your campaign <span>/</span> <b>${({deck:'The deck',missions:'Missions',skills:'Skills',rewards:'Reward shop',journal:'Activity log',settings:'Settings'})[page]}</b></div><div class="top-actions"><span class="coin">◉ <b>${state.profile.coins}</b><span> coins</span></span><button class="avatar-button" data-action="profile" aria-label="Edit profile">${state.profile.avatar?`<img src="${esc(state.profile.avatar)}" alt="">`:'✦'}</button></div></header><div class="main-content">${({deck:deck,missions:missions,skills:skills,rewards:rewards,journal:journal,settings:settings})[page]()}</div><footer>DAEMON DECK <span>Small steps. Real progress.</span><span>PRIVATE BY DESIGN ↗</span></footer></main><nav class="mobile-nav">${['deck','missions','skills','rewards','settings'].map(k=>`<button data-page="${k}" class="${page===k?'active':''}" aria-label="${k}">${icons[k]}<small>${k==='deck'?'Deck':k}</small></button>`).join('')}</nav>`;bind();}
function heading(k,title,desc,action){return `<div class="section-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${desc}</p></div>${action||''}</div>`}
function deck(){const p=progress(state.profile.xp),done=state.history.filter(h=>h.type==='complete'&&new Date(h.at).toDateString()===new Date().toDateString()).length,active=state.missions.filter(m=>m.status==='active'&&(!m.due||m.due<=today()));return `<section class="hero" ${state.settings.cover?`style="background-image:linear-gradient(90deg,#15231beb,#15231b77),url('${esc(state.settings.cover)}')"`:''}><div class="hero-copy"><div class="eyebrow"><i></i> THE NEXT CHAPTER IS YOURS</div><h1>A little better.<br>Every single day.</h1><p>Turn your everyday intentions into experience.<br>Pick a mission. Find your momentum.</p><button class="primary" data-action="new-mission">＋ Create a mission <span>↗</span></button></div><div class="hero-art" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><div class="star s1">✦</div><div class="star s2">✧</div><svg viewBox="0 0 320 300"><defs><linearGradient id="mount" x2="0" y2="1"><stop stop-color="#a4bca2"/><stop offset="1" stop-color="#314c3b"/></linearGradient></defs><circle cx="173" cy="116" r="56" fill="#d2b883" opacity=".88"/><path d="m20 261 87-142 43 73 48-98 103 167Z" fill="url(#mount)"/><path d="m107 119 18 68-18-16-20 22zM198 94l30 85-31-24-26 24z" fill="#d1d8bd"/><path d="m20 261 124-43 50 43z" fill="#243d2f"/><path d="m138 261 27-49-12-16 34-32" fill="none" stroke="#d6b87e" stroke-width="3" stroke-dasharray="4 5"/></svg><div class="art-caption">A JOURNEY, NOT A RACE <span>01 — ∞</span></div></div></section><div class="stat-grid"><div class="stat"><span class="stat-icon">✧</span><div><small>YOUR LEVEL</small><b>${p.level.toString().padStart(2,'0')} <em>Adventurer</em></b>${bar(state.profile.xp)}<small>${p.current} / ${p.total} XP to next level</small></div></div><div class="stat"><span class="stat-icon">⚑</span><div><small>MISSIONS COMPLETED TODAY</small><b>${done.toString().padStart(2,'0')} <em>Keep showing up</em></b><small>${state.history.filter(h=>h.type==='complete').length} completed in your journey</small></div></div><div class="stat"><span class="stat-icon">ϟ</span><div><small>YOUR ENERGY</small><b>${state.profile.energy}% <em>${state.profile.energy>65?'Ready to explore':'Take it at your pace'}</em></b><label class="sr-only" for="energy">Energy level</label><input id="energy" type="range" min="0" max="100" value="${state.profile.energy}"><small>Adjust to match how you feel</small></div></div></div><div class="deck-grid"><section><div class="block-heading"><div><span class="eyebrow">MAKE ROOM FOR PROGRESS</span><h2>Your next missions <small>${active.length}</small></h2></div><button class="text-button" data-page="missions">View all ↗</button></div><div class="tabs">${[['active','Up next'],['today','Due today'],['completed','Completed']].map(([k,l])=>`<button data-filter="${k}" class="${filter===k?'selected':''}">${l}</button>`).join('')}</div><div class="mission-list">${missionRows(getMissions().slice(0,5))}</div><button class="add-row" data-action="new-mission">＋ Add a little intention</button></section><aside class="right-rail"><div class="panel"><div class="block-heading"><h3>Your skill tree</h3><button class="text-button" data-page="skills">↗</button></div><p>Every quest leaves you a little stronger.</p>${state.skills.slice(0,4).map(s=>`<button class="skill-mini" data-edit="skill:${s.id}">${art(s)}<div><b>${esc(s.title)}<small>LVL ${level(s.xp)}</small></b>${bar(s.xp)}</div></button>`).join('')}</div><div class="quote-card"><span>✳</span><p>“You don't have to see the whole staircase. Just take the first step.”</p><small>A LITTLE REMINDER</small></div></aside></div>`}
function getMissions(){let ms=state.missions.filter(m=>filter==='completed'?m.status==='completed':filter==='failed'?m.status==='failed':m.status==='active'&&(filter!=='today'||m.due===today())&&(filter!=='overdue'||m.due&&m.due<today()));ms=ms.filter(m=>(selectedCategory==='all'||m.category===selectedCategory)&&`${m.title} ${m.description} ${m.category}`.toLowerCase().includes(query.toLowerCase()));return ms.sort((a,b)=>sort==='name'?a.title.localeCompare(b.title):sort==='xp'?xpFor(b)-xpFor(a):sort==='due'?(a.due||'9999').localeCompare(b.due||'9999'):score(b)-score(a))}
function score(m){return Number(m.urgency)*4+Number(m.fear)*2+(m.due&&m.due<today()?30:0)-(state.settings.energyAware&&state.profile.energy<40?Number(m.difficulty)*6:0)}
function missionRows(ms){return ms.length?ms.map(m=>`<article class="mission-row ${m.status==='completed'?'done':''}"><button class="complete" data-complete="${m.id}" ${m.status!=='active'?'disabled':''} aria-label="Complete ${esc(m.title)}">${m.status==='completed'?'✓':''}</button><button class="mission-main" data-edit="mission:${m.id}">${art(m)}<div><b>${esc(m.title)}</b><p>${esc(m.description)}</p><div class="metadata"><span class="tag">${esc(m.category||'Personal')}</span><span>◷ ${m.duration} min</span>${m.repeat!=='none'?'<span>↻ Repeats</span>':''}${m.due?`<span class="${m.due<today()&&m.status==='active'?'overdue':''}">${m.due===today()?'Today':esc(m.due)}</span>`:''}${m.subtasks.length?`<span>${m.subtasks.filter(t=>t.done).length}/${m.subtasks.length} steps</span>`:''}${m.parent?'<span>↳ Child mission</span>':''}</div></div></button><div class="mission-reward"><b>+${xpFor(m)} <small>XP</small></b><span>◉ ${m.coins}</span></div><button class="more" data-edit="mission:${m.id}" aria-label="Edit ${esc(m.title)}">⋯</button></article>`).join(''):`<div class="empty"><span>✧</span><h3>A little space for possibility</h3><p>No missions in this view. Create one or try another filter.</p></div>`}
function missions(){return heading('YOUR QUEST LOG','Big goals. Small steps.','Everything you’re working toward, in one place.','<button class="primary" data-action="new-mission">＋ New mission</button>')+`<div class="toolbar"><label class="search">⌕ <input id="search" placeholder="Find a mission…" value="${esc(query)}" aria-label="Search missions"></label><select id="category" aria-label="Filter category"><option value="all">All categories</option>${[...new Set(state.missions.map(m=>m.category))].map(c=>`<option ${c===selectedCategory?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="sort" aria-label="Sort missions">${[['suggested','Suggested order'],['due','Due date'],['xp','Highest XP'],['name','Alphabetical']].map(([k,v])=>`<option value="${k}" ${sort===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="tabs">${[['active','Active'],['today','Today'],['overdue','Overdue'],['completed','Completed'],['failed','Failed']].map(([k,l])=>`<button data-filter="${k}" class="${filter===k?'selected':''}">${l}</button>`).join('')}</div><div class="mission-list">${missionRows(getMissions())}</div>`}
function skills(){return heading('EXPERIENCE THAT STAYS WITH YOU','Grow in your own direction.','Tag missions with skills. Every completion helps them grow.','<button class="primary" data-action="new-skill">＋ New skill</button>')+`<div class="card-grid">${state.skills.map(s=>{const p=progress(s.xp);return `<article class="panel skill-card">${art(s)}<span class="card-kicker">${esc(s.category)}</span><h2>${esc(s.title)}</h2><p>${esc(s.description)}</p><div class="level-line"><b>Level ${p.level}</b><small>${s.xp} total XP</small></div>${bar(s.xp)}<p class="muted">${p.current} / ${p.total} XP to next level</p><button class="text-button" data-edit="skill:${s.id}">Customize skill ↗</button></article>`}).join('')}</div>`}
function rewards(){return heading('YOU’VE EARNED THIS','A little joy along the way.','Trade the coins you earn for rewards that mean something to you.','<button class="primary" data-action="new-reward">＋ New reward</button>')+`<div class="reward-banner"><span>◉</span><div><small>YOUR COIN BALANCE</small><h2>${state.profile.coins} <small>coins to spend on yourself</small></h2></div></div><div class="card-grid">${state.rewards.map(r=>`<article class="panel reward-card">${art(r)}<span class="card-kicker">${esc(r.category)}</span><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><p class="muted">${r.quantity<0?'Always available':`${r.quantity} in stock`} · Redeemed ${r.purchases} times</p><div class="card-actions"><button class="primary" data-buy="${r.id}" ${state.profile.coins<r.cost||r.quantity===0?'disabled':''}>Redeem · ◉ ${r.cost}</button><button class="more" data-edit="reward:${r.id}" aria-label="Edit reward">⋯</button></div>${r.inventory?`<div class="inventory">${r.inventory} in your inventory <button class="text-button" data-use="${r.id}">Use one ↗</button></div>`:''}</article>`).join('')}</div>`}
function journal(){return heading('YOUR STORY SO FAR','Proof of showing up.','A record of your completed missions and well-earned rewards.')+`<div class="panel history">${state.history.length?state.history.map(h=>`<div class="history-row"><span>${h.type==='complete'?'✓':h.type==='fail'?'×':'♜'}</span><div><b>${esc(h.title)}</b><p>${esc(new Date(h.at).toLocaleString())}</p></div><div>${h.xp?`+${h.xp} XP`:''}<small>${h.coins||0} coins</small></div></div>`).join(''):'<div class="empty"><span>▤</span><h3>Your story starts with one mission.</h3><p>Your progress will appear here.</p></div>'}</div>`}
function settings(){return heading('MAKE IT FEEL LIKE YOU','Your deck. Your rules.','Customize your space and keep your progress in your hands.')+`<div class="settings-grid"><section class="panel"><h2>Look & feel</h2><p>A space you’ll want to come back to.</p><label class="setting">Accent color<input type="color" id="accent" value="${esc(state.settings.accent)}"></label><label class="setting">Light appearance<input type="checkbox" id="light" ${state.settings.light?'checked':''}></label><label class="setting">Compact mission rows<input type="checkbox" id="compact" ${state.settings.compact?'checked':''}></label><label class="setting">Adapt suggested order to my energy<input type="checkbox" id="energyAware" ${state.settings.energyAware?'checked':''}></label><label class="file-button">↑ Upload dashboard cover<input id="cover" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label>${state.settings.cover?'<button class="text-button" data-action="clear-cover">Remove cover</button>':''}<button class="secondary" data-action="profile">Edit profile & avatar ↗</button></section><section class="panel"><h2>Your data, in your hands</h2><p>Progress and uploaded images stay on this device. Export a backup to move between the web and Android apps.</p><button class="secondary" data-action="export">↓ Export complete backup</button><label class="file-button">↑ Import Daemon Deck backup<input id="import" type="file" accept="application/json,.json"></label><p class="muted">Backups include your profile, missions, skills, rewards, history, and custom images. Import replaces this device’s data after confirmation.</p><hr>${window.DaemonNative?'':`<h3>Take your deck with you</h3><a class="secondary" href="downloads/daemon-deck-debug.apk" download>↓ Download Android APK</a><a class="secondary" href="downloads/daemon-deck-source.zip" download>↓ Download project source</a><p class="muted">Development APK · Android 8+ · Export a backup before reinstalling. Device testing is still pending.</p><hr>`}<h3>About Daemon Deck</h3><p>Version 0.1.0 · Offline-first web & Android<br>Inspired by the life RPG approach. Built for your next chapter.</p><button class="text-button" data-action="install">Install web app ↗</button></section></div>`}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;filter='active';query='';selectedCategory='all';render();window.scrollTo(0,0)});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const [type,id]=b.dataset.edit.split(':');openEditor(type,id)});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{try{const xp=complete(state,b.dataset.complete);if(xp!==null){save();render();toast(`Mission complete. +${xp} XP — keep becoming.`)}}catch(e){toast(e.message);openEditor('mission',b.dataset.complete)}});document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{try{purchase(state,b.dataset.buy);save();render();toast('Reward redeemed. Find it in your inventory.')}catch(e){toast(e.message)}});document.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{const r=state.rewards.find(r=>r.id===b.dataset.use);if(r.inventory>0){r.inventory--;save();render();toast('Enjoy your reward. You earned it.')}});if($('#energy'))$('#energy').onchange=e=>{state.profile.energy=+e.target.value;save();render()};if($('#search'))$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};for(const id of ['sort','category'])if($('#'+id))$('#'+id).onchange=e=>{if(id==='sort')sort=e.target.value;else selectedCategory=e.target.value;render()};for(const id of ['accent','light','compact','energyAware'])if($('#'+id))$('#'+id).onchange=e=>{state.settings[id]=e.target.type==='checkbox'?e.target.checked:e.target.value;save();render()};if($('#cover'))$('#cover').onchange=async e=>{try{state.settings.cover=await readImage(e.target.files[0]);save();render()}catch(e){toast(e.message)}};if($('#import'))$('#import').onchange=importBackup;}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function openEditor(type,id){const collection=type==='mission'?'missions':type==='skill'?'skills':'rewards';const old=state[collection]?.find(x=>x.id===id);editorContext={type,id};editingImage=old?.image||'';const x=old||{title:'',description:'',icon:'✧',category:'Personal',difficulty:2,urgency:2,fear:1,duration:20,coins:15,skills:[],repeat:'none',due:today(),notes:'',subtasks:[],cost:50,quantity:-1,increase:0};$('#editor').innerHTML=`<form id="item-form"><div class="modal-heading"><div><span class="eyebrow">YOUR NEXT CHAPTER</span><h2>${type==='profile'?'Make yourself at home':`${old?'Edit':'Create'} ${type}`}</h2></div><button type="button" class="close" data-close aria-label="Close">×</button></div>${type==='profile'?`${field('Your name','name',state.profile.name,'text','required maxlength="60"')}${field('Your personal motto','title',state.profile.title,'text','maxlength="100"')}<label class="file-button">↑ Upload your avatar<input name="image" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label><img class="image-preview" ${state.profile.avatar?`src="${esc(state.profile.avatar)}"`: 'hidden'} alt="Avatar preview"><label class="check-label"><input type="checkbox" name="removeImage"> Remove custom avatar</label>`:`${field('Name','title',x.title,'text','required maxlength="160"')}<label class="field">Description<textarea name="description" rows="2" maxlength="3000">${esc(x.description)}</textarea></label><div class="form-grid">${field('Category','category',x.category,'text','maxlength="60"')}${field('Icon / emoji','icon',x.icon,'text','maxlength="12"')}</div><label class="file-button">↑ Upload your own icon or image<input name="image" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label><img class="image-preview" ${x.image?`src="${esc(x.image)}"`:'hidden'} alt="Custom image preview"><label class="check-label"><input name="removeImage" type="checkbox"> Remove uploaded image</label>${type==='mission'?`<div class="form-grid">${field('Due date','due',x.due,'date')}${field('Estimated minutes','duration',x.duration,'number','min="1" max="100000" required')}${field('Coins earned','coins',x.coins,'number','min="0" max="1000000" required')}<label class="field">Repeats<select name="repeat">${['none','daily','weekly','monthly'].map(v=>`<option ${x.repeat===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="range-fields">${['difficulty','urgency','fear'].map(n=>`<label class="field">${n[0].toUpperCase()+n.slice(1)} <output id="${n}-value">${x[n]}</output><input type="range" name="${n}" min="0" max="5" value="${x[n]}"></label>`).join('')}</div><div class="xp-preview">✧ This mission earns <b id="xp-preview">${xpFor(x)} XP</b></div><label class="field">Parent mission<select name="parent"><option value="">No parent · standalone mission</option>${state.missions.filter(m=>m.id!==id&&m.status==='active'&&!isDescendant(m.id,id)).map(m=>`<option value="${m.id}" ${x.parent===m.id?'selected':''}>${esc(m.title)}</option>`).join('')}</select></label><fieldset><legend>Skills to develop</legend>${state.skills.map(s=>`<label class="skill-check"><input type="checkbox" name="skills" value="${s.id}" ${x.skills.includes(s.id)?'checked':''}>${esc(s.icon)} ${esc(s.title)}</label>`).join('')}</fieldset><label class="field">Subtasks <small>One step per line. Check steps below to complete them.</small><textarea name="steps" rows="3">${esc(x.subtasks.map(t=>t.title).join('\n'))}</textarea></label>${x.subtasks.map((t,i)=>`<label class="check-label"><input type="checkbox" name="stepdone" value="${i}" ${t.done?'checked':''}>${esc(t.title)}</label>`).join('')}<label class="field">Location <small>Optional address or place</small><input name="location" value="${esc(x.location||'')}" maxlength="300"></label>`:type==='reward'?`<div class="form-grid">${field('Cost in coins','cost',x.cost,'number','min="0" max="1000000" required')}${field('Stock (−1 = unlimited)','quantity',x.quantity,'number','min="-1" max="1000000" required')}${field('Cost increase per purchase','increase',x.increase,'number','min="0" max="1000000" required')}</div>`:''}${type!=='reward'?`<label class="field">Private notes<textarea name="notes" rows="3" maxlength="20000">${esc(x.notes)}</textarea></label>`:''}` }<div class="modal-actions">${old?`<button type="button" class="danger" data-delete>Delete</button>${type==='mission'?`<button type="button" class="secondary" data-status>${old.status==='active'?'Mark failed':'Reopen'}</button><button type="button" class="secondary" data-duplicate>Duplicate</button>`:''}`:''}<span></span><button type="button" class="secondary" data-close>Cancel</button><button class="primary" type="submit">Save ${type==='profile'?'profile':type}</button></div></form>`;if(type==='profile')editingImage=state.profile.avatar;const modal=$('#editor');if(!modal.open)modal.showModal();modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close());const upload=modal.querySelector('[name=image]');upload.onchange=async e=>{try{editingImage=await readImage(e.target.files[0]);const preview=modal.querySelector('.image-preview');preview.src=editingImage;preview.hidden=false}catch(e){toast(e.message)}};modal.querySelectorAll('input[type=range]').forEach(r=>r.oninput=()=>{modal.querySelector('#'+r.name+'-value').value=r.value;const f=new FormData($('#item-form'));$('#xp-preview').textContent=xpFor(Object.fromEntries(f))+' XP'});if(modal.querySelector('[data-delete]'))modal.querySelector('[data-delete]').onclick=()=>{if(!confirm(`Delete “${old.title}”? This cannot be undone.`))return;state[collection]=state[collection].filter(i=>i.id!==id);if(type==='skill')state.missions.forEach(m=>m.skills=m.skills.filter(s=>s!==id));if(type==='mission')state.missions.forEach(m=>{if(m.parent===id)m.parent=''});save();modal.close();render()};if(modal.querySelector('[data-status]'))modal.querySelector('[data-status]').onclick=()=>{if(old.status!=='active'&&old.status==='completed'){toast('Duplicate a completed mission to repeat it without counting XP twice.');return}old.status=old.status==='active'?'failed':'active';if(old.status==='failed')state.history.unshift({id:uid(),type:'fail',title:old.title,at:new Date().toISOString()});save();modal.close();render()};if(modal.querySelector('[data-duplicate]'))modal.querySelector('[data-duplicate]').onclick=()=>{state.missions.push({...structuredClone(old),id:uid(),title:old.title+' (copy)',status:'active',parent:'',subtasks:old.subtasks.map(t=>({...t,done:false}))});save();modal.close();render()};$('#item-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v=Object.fromEntries(f);if(type==='profile'){state.profile.name=v.name.trim()||'Adventurer';state.profile.title=v.title;state.profile.avatar=v.removeImage?'':editingImage}else{if(!v.title.trim()){toast('Give this a name first.');return}let item={...old,id:id||uid(),title:v.title.trim(),description:v.description,category:v.category,icon:v.icon||'✧',image:v.removeImage?'':editingImage};if(type==='mission'){Object.assign(item,{duration:+v.duration,coins:+v.coins,difficulty:+v.difficulty,urgency:+v.urgency,fear:+v.fear,repeat:v.repeat,due:v.due,skills:f.getAll('skills'),parent:v.parent,notes:v.notes,location:v.location,status:old?.status||'active',subtasks:v.steps.split('\n').map(t=>t.trim()).filter(Boolean).map(t=>{const i=x.subtasks.findIndex(s=>s.title===t);return {title:t,done:i>=0&&f.getAll('stepdone').includes(String(i))}})})}if(type==='skill')Object.assign(item,{xp:old?.xp||0,notes:v.notes});if(type==='reward')Object.assign(item,{cost:+v.cost,quantity:+v.quantity,increase:+v.increase,purchases:old?.purchases||0,inventory:old?.inventory||0});if(old)state[collection]=state[collection].map(o=>o.id===id?item:o);else state[collection].push(item)}save();modal.close();render();toast('Saved. Make it your own.')};}
function isDescendant(child,parent){const seen=new Set();let id=child;while(id&&!seen.has(id)){if(id===parent)return true;seen.add(id);id=state.missions.find(m=>m.id===id)?.parent}return false}
async function readImage(file){if(!file)throw Error('Choose an image first.');if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error('Use a PNG, JPG, WebP, or GIF image.');if(file.size>10*1024*1024)throw Error('Choose an image smaller than 10 MB.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Could not read image.'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(Error('This image could not be opened.'));image.onload=()=>{const canvas=document.createElement('canvas'),ratio=Math.min(1,1400/Math.max(image.width,image.height));canvas.width=image.width*ratio;canvas.height=image.height*ratio;canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/webp',.8))};image.src=reader.result};reader.readAsDataURL(file)})}
async function importBackup(e){try{const file=e.target.files[0];if(!file)return;if(file.size>25*1024*1024)throw Error('Backup is too large (25 MB maximum).');const incoming=validate(JSON.parse(await file.text()));if(!confirm('Replace all progress on this device with this backup? Export your current progress first if you want to keep it.'))return;state=incoming;save();render();toast('Your journey is restored.')}catch(e){toast(e.message||'Could not read that backup.')}}
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
function action(a){if(a.startsWith('new-'))return openEditor(a.slice(4));if(a==='profile')return openEditor('profile');if(a==='clear-cover'){state.settings.cover='';save();render()}if(a==='export'){const content=JSON.stringify(state,null,2),name=`daemon-deck-${today()}.json`;if(window.DaemonNative){window.DaemonNative.exportBackup(content,name);return}const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}if(a==='install'){if(installPrompt){installPrompt.prompt();installPrompt=null}else toast('Use your browser menu → Install app or Add to Home Screen.')}}
